const pages = __webpack_require__(/*! ../../fixtures/pages.json */ "./cypress/fixtures/pages.json");
const offenders = [];
cy.viewport(w, h);
pages.forEach(p => {
  cy.visitPage(p.path);
  cy.document().then(d => {
    const o = d.documentElement.scrollWidth - d.documentElement.clientWidth;
    if (o > 1) offenders.push(`${p.path} +${o}px`);
  });
});
cy.then(() => {
  cy.task('evidence', {
    kind: 'responsive',
    record: {
      scan: `${w}px`,
      offenders
    }
  });
  expect(offenders, `pages wider than ${w}px`).to.deep.equal([]);
});

